import type { ComponentMeta, ComponentProp } from "./types";
import { propsMap } from "./components/props-map";

/**
 * Resolves the props table for a component.
 *
 * `manualProps` is reserved for compound components whose public API is a set of
 * parts rather than a single Props type. Everything else comes from JSDoc on the
 * exported *Props type in the kit source and is regenerated by `gen:props`.
 */
export function getComponentProps(meta: ComponentMeta): ComponentProp[] {
  if (meta.manualProps) return meta.manualProps;

  const generated = propsMap[meta.slug] ?? [];
  const extra = (meta.extraProps ?? []).filter(
    (prop) => !generated.some((generatedProp) => generatedProp.name === prop.name),
  );
  return [...generated, ...extra];
}
